package autoupdate

import (
	"context"
	"crypto/sha512"
	"encoding/hex"
	"errors"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
	"testing"

	"github.com/obentoo/bentoolkit/internal/autoupdate/fetch"
)

// A CDN that keeps a cached 404 for the plain URL while the origin, reached
// through a fresh query string, serves the generated bytes is told apart from
// an object that was never served, and the error names the purge.
func TestCachedNotFoundNamesThePurge(t *testing.T) {
	const body = "tarball bytes"
	sum := sha512.Sum512([]byte(body))
	for _, tc := range []struct {
		name      string
		originHas bool
		wantPurge bool
	}{
		{"cached 404 over a served object", true, true},
		{"never served", false, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				if tc.originHas && r.URL.RawQuery != "" {
					_, _ = w.Write([]byte(body))
					return
				}
				http.NotFound(w, r)
			}))
			defer srv.Close()
			a := &Applier{httpClient: fetch.NewRetryableHTTPClient()}
			out := VendorOutcome{URI: srv.URL + "/x-1.0-vendor.tar.xz", SHA512: hex.EncodeToString(sum[:])}

			err := a.cachedNotFound(context.Background(), out)
			purge := err != nil && strings.Contains(err.Error(), "purge "+out.URI)
			if purge != tc.wantPurge {
				t.Fatalf("cachedNotFound = %v; want purge named: %v", err, tc.wantPurge)
			}
			if !tc.wantPurge && !errors.Is(err, errServedNotFound) {
				t.Fatalf("cachedNotFound = %v; want errServedNotFound", err)
			}
		})
	}
}

// Long argv values are masked in the upload output; short words are kept.
func TestRedactArgvMasksLongValues(t *testing.T) {
	got := redactArgv("> Authorization: Bearer s3cr3t-token-value\n-v ok",
		[]string{"-H", "Authorization: Bearer s3cr3t-token-value", "-v"})
	if strings.Contains(got, "s3cr3t") || !strings.Contains(got, "<argv>") || !strings.Contains(got, "-v ok") {
		t.Fatalf("redactArgv = %q", got)
	}
}

// The debug line naming the upload command shows the program and the
// placeholders, and masks a literal credential written into the command.
func TestLoggableUploadCommandMasksLiteralCredentials(t *testing.T) {
	got := loggableUploadCommand([]string{"curl", "-H", "Authorization: Bearer s3cr3t-token-value", "-T", "{path}", "https://up.example.org/{file}"})
	want := []string{"curl", "-H", "<argv>", "-T", "{path}", "https://up.example.org/{file}"}
	if !slices.Equal(got, want) {
		t.Fatalf("loggableUploadCommand = %q, want %q", got, want)
	}
}
